import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'

    # Compress history into counts and scores
    my_score = 0
    op_score = 0
    opp_c = 0
    opp_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for a, b in history:
        if a == 'C':
            if b == 'C':
                my_score += 3
                op_score += 3
                cc += 1
            else:
                op_score += 5
                cd += 1
        else:
            if b == 'C':
                my_score += 5
                dc += 1
            else:
                my_score += 1
                op_score += 1
                dd += 1
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

    last_my, last_op = history[-1]
    remaining = 100 - n

    # Long-run opponent defection rate
    opp_def_rate = opp_d / n

    # Opponent is essentially always cooperating: exploit moderately late,
    # but keep cooperation alive in the middle of the match.
    if opp_d == 0:
        if remaining <= 3:
            if rng.random() < 0.55:
                return 'D'
        # mild rare probing to capture extra value, low enough to not trigger retaliation
        if n >= 40 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Opponent basically always defects: punish hard, with rare reset attempts
    if opp_c == 0:
        # Occasionally try C to see if they've softened, but mostly D
        if n >= 10 and (opp_d % 25 == 0) and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Recent opponent behavior window
    window = 8 if n >= 8 else n
    recent = history[-window:]
    recent_opp_d = 0
    recent_opp_c = 0
    for a, b in recent:
        if b == 'D':
            recent_opp_d += 1
        else:
            recent_opp_c += 1

    # Very recent (last 3) opponent moves for quick reaction
    last3 = history[-3:]
    last3_d = 0
    for a, b in last3:
        if b == 'D':
            last3_d += 1

    # If we've fallen behind significantly, become more aggressive
    behind = op_score - my_score

    # If opponent just defected:
    if last_op == 'D':
        # Hard retaliation if they've been defecting a lot recently
        if recent_opp_d >= 4:
            return 'D'
        # If opponent overall is fairly cooperative, retaliate once but be ready to forgive.
        if opp_def_rate < 0.25:
            # If we already defected last round and they still defected, forgive back to C
            # to avoid long mutual defection with a mostly-cooperative opponent.
            if last_my == 'D':
                if rng.random() < 0.6:
                    return 'C'
                return 'D'
            return 'D'
        # Mixed opponent: retaliate but occasionally reset
        if behind > 10 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If opponent has been mostly cooperative recently, cooperate but consider occasional exploitation.
    if recent_opp_d == 0:
        # Long cooperation streak: exploit sparingly when it likely won't trigger collapse.
        if opp_c >= 10:
            # Endgame exploitation
            if remaining <= 2:
                if rng.random() < 0.5:
                    return 'D'
            # Occasional probe when we are behind, or randomly very rarely
            if behind > 6 and rng.random() < 0.2:
                return 'D'
            if n >= 30 and rng.random() < 0.05:
                return 'D'
        return 'C'

    if recent_opp_d <= 1:
        # Opponent mildly cooperative: cooperate, with light probing
        if behind > 8 and rng.random() < 0.18:
            return 'D'
        return 'C'

    if recent_opp_d >= 5:
        # Opponent recently defecting often despite last being C: defect
        return 'D'

    # Mixed zone (2-4 defections in window)
    # Opponent defected in last 3 recently but just cooperated: cautiously cooperate,
    # but be ready to defect if they continue defecting.
    if last3_d >= 2:
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    # Cooperative default in mixed zone
    if behind > 12 and rng.random() < 0.25:
        return 'D'
    return 'C'
